import torch
from torch.utils.cpp_extension import load_inline

src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <vector>
#include <float.h>

__global__ void softmax_kernel(const __half* __restrict__ input,
                               __half* __restrict__ output,
                               int dim) {
    int row = blockIdx.x;          // one block per batch element
    int tid = threadIdx.x;         // thread index inside the block

    // ---------- max reduction ----------
    float max_val = -FLT_MAX;
    for (int i = tid; i < dim; i += blockDim.x) {
        float v = __half2float(input[row * dim + i]);
        if (v > max_val) max_val = v;
    }

    // shared memory: first part for max, second part for sum
    extern __shared__ float shmem[];
    float* smax = shmem;                     // size = blockDim.x
    float* ssum = shmem + blockDim.x;        // size = blockDim.x

    smax[tid] = max_val;
    __syncthreads();

    // parallel reduction to obtain the row max
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            if (smax[tid + stride] > smax[tid])
                smax[tid] = smax[tid + stride];
        }
        __syncthreads();
    }
    float row_max = smax[0];

    // ---------- sum of exp ----------
    float sum = 0.0f;
    for (int i = tid; i < dim; i += blockDim.x) {
        float v = __half2float(input[row * dim + i]);
        sum += expf(v - row_max);
    }
    ssum[tid] = sum;
    __syncthreads();

    // parallel reduction to obtain the row sum
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            ssum[tid] += ssum[tid + stride];
        }
        __syncthreads();
    }
    float row_sum = ssum[0];

    // ---------- write softmax ----------
    for (int i = tid; i < dim; i += blockDim.x) {
        float v = __half2float(input[row * dim + i]);
        float out = expf(v - row_max) / row_sum;
        output[row * dim + i] = __float2half(out);
    }
}

// Wrapper called from Python
void softmax_fp16_cuda(at::Tensor input, at::Tensor output) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(output.is_cuda(), "output must be a CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kHalf, "Only fp16 (half) supported");
    TORCH_CHECK(output.dtype() == torch::kHalf, "Only fp16 (half) supported");
    TORCH_CHECK(input.sizes() == output.sizes(), "input and output must have same shape");

    const int batch = input.size(0);
    const int dim   = input.size(1);

    const int threads = 1024;                     // max threads per block on A100
    const dim3 blocks(batch);
    const size_t shared_mem = 2 * threads * sizeof(float); // max + sum

    softmax_kernel<<<blocks, threads, shared_mem, at::cuda::getCurrentCUDAStream()>>>(
        reinterpret_cast<const __half*>(input.data_ptr<torch::Half>()),
        reinterpret_cast<__half*>(output.data_ptr<torch::Half>()),
        dim
    );

    // propagate possible launch errors
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA softmax kernel launch failed: ", cudaGetErrorString(err));
    }
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("softmax_fp16_cuda", &softmax_fp16_cuda, "Softmax over dim=1 (fp16) CUDA kernel");
}
'''

# compile the inline extension
softmax_ext = load_inline(
    name="softmax_fp16_ext",
    cpp_sources="",
    cuda_sources=src,
    functions=["softmax_fp16_cuda"],
    verbose=False,
)

class ModelNew(torch.nn.Module):
    """
    Drop‑in replacement for the reference Model.
    Performs Softmax over dimension 1 using a custom fp16 CUDA kernel.
    """
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        out = torch.empty_like(x)
        softmax_ext.softmax_fp16_cuda(x, out)
        return out
